final class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(handler => handler(item))
            .find(_.isDefined)
            .flatten
        }.toList
    }
  }
}

// ============================================================================
// Higher-Kinded Type Simulation
// ============================================================================

class TokenFunctor[T](protected val value: T) {
  def map[B](func: T => B): TokenFunctor[B] = new TokenFunctor(func(value))
  def flatMap[B](func: T => TokenFunctor[B]): TokenFunctor[B] = func(value)
  def getOrElse(default: => T): T = Option(value).getOrElse(default)
  def get: T = value
}

final class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[B](funcWrapped: TokenMonad[T => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped.get.apply(value))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

object JsonTokenizer {
  type JsonValue = Json
}

final class JsonTokenizer(pretty: Boolean = false) {
  import JsonTokenizer.JsonValue

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toVector

    val extracted = parts.foldLeft(Option(value)) { (currentOpt, part) =>
      currentOpt.flatMap { current =>
        current.asObject.flatMap(_.apply(part))
          .orElse {
            if (part.forall(_.isDigit)) {
              val idx = part.toInt
              current.asArray.flatMap(arr => arr.lift(idx))
            } else {
              None
            }
          }
      }
    }

    extracted.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def trimPunctuation(word: String): String = {
    val leftTrimmed = word.dropWhile(punctuation.contains)
    leftTrimmed.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) trimPunctuation(word) else word
    val lowered = if (lowercase) stripped.toLowerCase else stripped

    if (lowered.length < minLength) {
      None
    } else {
      val truncated = maxLength match {
        case Some(limit) if lowered.length > limit => lowered.take(limit)
        case _ => lowered
      }
      if (truncated.nonEmpty) Some(truncated) else None
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toVector

    words.zipWithIndex.flatMap { case (word, index) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> index, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toVector
    val result = mutable.ListBuffer.empty[(String, Int, Int)]

    var currentPos = 0
    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }
      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] {
  private val normalizers: mutable.ListBuffer[String => String] = mutable.ListBuffer.empty
  private val validators: mutable.ListBuffer[T => Boolean] = mutable.ListBuffer.empty
  private val metadata: mutable.Map[String, Any] = mutable.Map.empty

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= entries
    this
  }

  def withMetadata(entries: Map[String, Any]): TokenizerBuilder[T] = {
    metadata ++= entries
    this
  }

  def build(): T => Token = {
    val normalizerChain = normalizers.toVector
    val validatorChain = validators.toVector
    val metadataSnapshot = metadata.toMap

    (value: T) => {
      validatorChain.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = normalizerChain.foldLeft(value.toString) { (current, normalize) =>
        normalize(current)
      }

      Token(normalized, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
